import { PageContainer, ProTable, ModalForm, ProFormText, ProFormDigit, ProFormSelect } from '@ant-design/pro-components';
import { Button, Tag, Image, message, Popconfirm, Space, Form, Upload, Input } from 'antd';
import { PlusOutlined, EditOutlined, DeleteOutlined, VerticalAlignTopOutlined, VerticalAlignBottomOutlined, LoadingOutlined, UploadOutlined } from '@ant-design/icons';
import { useRef, useState, useCallback } from 'react';
import { request } from '@umijs/max';
import { compressImage, isLargeImage } from '@/utils/imageCompress';
import dayjs from 'dayjs';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';

const statusMap: Record<number, { text: string; color: string }> = {
  0: { text: '草稿', color: 'default' },
  1: { text: '已发布', color: 'success' },
  2: { text: '已下架', color: 'error' },
};

const quillFormats = [
  'header',
  'bold', 'italic', 'underline', 'strike',
  'list', 'bullet', 'indent',
  'color', 'background',
  'link', 'image',
];

export default function ReviewManage() {
  const tableRef = useRef<any>(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [editData, setEditData] = useState<any>(null);
  const [content, setContent] = useState('');
  const [coverImageUrl, setCoverImageUrl] = useState('');
  const [coverUploading, setCoverUploading] = useState(false);
  const [gallery, setGallery] = useState<string[]>([]);
  const [form] = Form.useForm();
  const quillRef = useRef<ReactQuill>(null);

  const handleQuillImageUpload = useCallback(() => {
    const input = document.createElement('input');
    input.setAttribute('type', 'file');
    input.setAttribute('accept', 'image/*');
    input.click();
    input.onchange = async () => {
      const file = input.files?.[0];
      if (!file) return;
      try {
        // 大图先压缩
        const uploadFile = isLargeImage(file) ? await compressImage(file) : file;
        const formData = new FormData();
        formData.append('file', uploadFile);
        const token = localStorage.getItem('token');
        const res = await fetch('/api/v1/files/upload/image', {
          method: 'POST',
          headers: {
            ...(token ? { Authorization: `Bearer ${token}` } : {}),
          },
          body: formData,
        });
        const data = await res.json();
        if (data.code === 200 && data.data?.url) {
          const editor = quillRef.current?.getEditor();
          if (editor) {
            const range = editor.getSelection(true);
            editor.insertEmbed(range.index, 'image', data.data.url);
            editor.setSelection(range.index + 1);
          }
          message.success('图片插入成功');
        } else {
          message.error(data.message || '图片上传失败');
        }
      } catch (error) {
        message.error('图片上传失败');
      }
    };
  }, []);

  const quillModules = useRef({
    toolbar: {
      container: [
        [{ header: [1, 2, 3, false] }],
        ['bold', 'italic', 'underline', 'strike'],
        [{ list: 'ordered' }, { list: 'bullet' }],
        [{ indent: '-1' }, { indent: '+1' }],
        [{ color: [] }, { background: [] }],
        ['link', 'image'],
        ['clean'],
      ],
      handlers: {
        image: handleQuillImageUpload,
      },
    },
  }).current;

  const openModal = (record?: any) => {
    setEditData(record || null);
    setContent(record?.content || '');
    setCoverImageUrl(record?.cover_image || '');
    let galleryUrls: string[] = [];
    if (record?.images) {
      try {
        galleryUrls = typeof record.images === 'string' ? JSON.parse(record.images) : record.images;
      } catch (e) {
        console.error('[Modal] Failed to parse images:', record.images, e);
      }
    }
    setGallery(galleryUrls);
    form.setFieldsValue(record || { status: 0, is_top: 0, sort_order: 0, category: 'review', participants: 0 });
    setModalVisible(true);
  };

  const handleDelete = async (id: number) => {
    try {
      const res = await request('/api/v1/admin/articles/' + id, { method: 'DELETE' });
      if (res.code === 200) {
        message.success('删除成功');
        tableRef.current?.reload();
      } else {
        message.error(res.message || '删除失败');
      }
    } catch (error) {
      message.error('删除失败');
    }
  };

  const handleStatusChange = async (record: any, newStatus: number) => {
    try {
      const res = await request('/api/v1/admin/articles/' + record.id, {
        method: 'PUT',
        data: { ...record, status: newStatus },
      });
      if (res.code === 200) {
        message.success('状态更新成功');
        tableRef.current?.reload();
      } else {
        message.error(res.message || '更新失败');
      }
    } catch (error) {
      message.error('更新失败');
    }
  };

  const handleCoverUpload = async (file: File) => {
    setCoverUploading(true);
    try {
      // 大图先压缩
      const uploadFile = isLargeImage(file) ? await compressImage(file) : file;
      const formData = new FormData();
      formData.append('file', uploadFile);
      const token = localStorage.getItem('token');
      const res = await fetch('/api/v1/files/upload/image', {
        method: 'POST',
        headers: {
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: formData,
      });
      const data = await res.json();
      if (data.code === 200 && data.data?.url) {
        setCoverImageUrl(data.data.url);
        form.setFieldsValue({ cover_image: data.data.url });
        message.success('上传成功');
      } else {
        message.error(data.message || '上传失败');
      }
    } catch (error) {
      message.error('上传失败');
    } finally {
      setCoverUploading(false);
    }
    return false;
  };

  // 添加图集图片（使用函数式更新避免 stale closure）
  const handleGalleryUpload = (url: string) => {
    setGallery(prev => {
      const newGallery = [...prev, url];
      return newGallery;
    });
  };

  // 删除图集图片
  const removeGalleryImage = (index: number) => {
    setGallery(prev => {
      const newGallery = prev.filter((_, i) => i !== index);
      return newGallery;
    });
  };

  // 图集上传配置
  const galleryUploadProps = {
    name: 'file',
    action: '/api/v1/files/upload/image',
    headers: {
      Authorization: `Bearer ${localStorage.getItem('token') || ''}`,
    },
    beforeUpload: async (file: File) => {
      if (isLargeImage(file)) {
        message.loading('图片压缩中...', 0);
        try {
          const compressed = await compressImage(file);
          message.destroy();
          return compressed;
        } catch (e) {
          message.destroy();
          message.error('图片压缩失败，使用原图上传');
        }
      }
      return file;
    },
    onChange(info: any) {
      if (info.file.status === 'done') {
        const url = info.file.response?.data?.url;
        if (url) {
          message.success(`${info.file.name} 上传成功`);
          handleGalleryUpload(url);
        } else {
          console.error('[Upload] No URL in response:', info.file.response);
          message.error('上传成功但无法获取图片地址');
        }
      } else if (info.file.status === 'error') {
        message.error(`${info.file.name} 上传失败`);
        console.error('[Upload] Error:', info.file.error);
      }
    },
  };

  const handleSubmit = async (values: any) => {
    try {
      const url = editData ? '/api/v1/admin/articles/' + editData.id : '/api/v1/admin/articles';
      const method = editData ? 'PUT' : 'POST';
      const submitContent = content && content.trim() !== '<p><br></p>' ? content : '';
      // 从 form 实例获取完整字段值，避免 ModalForm onFinish 遗漏
      const allValues = form.getFieldsValue(true);
      // 清理数字字段空字符串，避免后端类型转换失败
      const submitData = {
        ...allValues,
        content: submitContent,
        category: 'review',
        is_top: allValues.is_top === '' || allValues.is_top === undefined ? 0 : Number(allValues.is_top),
        sort_order: allValues.sort_order === '' || allValues.sort_order === undefined ? 0 : Number(allValues.sort_order),
        participants: allValues.participants === '' || allValues.participants === undefined ? 0 : Number(allValues.participants),
        status: allValues.status === '' || allValues.status === undefined ? 0 : Number(allValues.status),
        images: gallery.length > 0 ? JSON.stringify(gallery) : null,
      };
      const res = await request(url, {
        method,
        data: submitData,
      });
      if (res.code === 200) {
        message.success(editData ? '更新成功' : '创建成功');
        setModalVisible(false);
        setEditData(null);
        setContent('');
        setCoverImageUrl('');
        setGallery([]);
        tableRef.current?.reload();
        return true;
      }
      message.error(res.message || (editData ? '更新失败' : '创建失败'));
      return false;
    } catch (error: any) {
      message.error(error?.message || (editData ? '更新失败' : '创建失败'));
      return false;
    }
  };

  const columns = [
    { title: 'ID', dataIndex: 'id', width: 60, search: false },
    {
      title: '封面',
      dataIndex: 'cover_image',
      width: 100,
      search: false,
      render: (url: string) => {
        if (!url) return <span style={{ color: '#999' }}>无</span>;
        const fullUrl = url;
        return <Image src={fullUrl} width={80} height={60} style={{ objectFit: 'cover' }} />;
      },
    },
    {
      title: '标题',
      dataIndex: 'title',
      width: 250,
      ellipsis: true,
      render: (text: string, record: any) => (
        <div>
          <div>{text}</div>
          {record.is_top === 1 && <Tag color="red" size="small">置顶</Tag>}
        </div>
      ),
    },
    {
      title: '地点',
      dataIndex: 'location',
      width: 150,
      ellipsis: true,
    },
    {
      title: '活动日期',
      dataIndex: 'event_date',
      width: 120,
      search: false,
    },
    {
      title: '参与狗狗',
      dataIndex: 'participants',
      width: 100,
      search: false,
      render: (v: number) => `${v || 0} 只`,
    },
    { title: '浏览', dataIndex: 'view_count', width: 80, search: false },
    {
      title: '状态',
      dataIndex: 'status',
      width: 100,
      valueEnum: {
        0: { text: '草稿', status: 'Default' },
        1: { text: '已发布', status: 'Success' },
        2: { text: '已下架', status: 'Error' },
      },
    },
    {
      title: '发布时间',
      dataIndex: 'created_at',
      width: 180,
      search: false,
      render: (date: string) => (date ? dayjs(date).format('YYYY-MM-DD HH:mm') : '-'),
    },
    {
      title: '操作',
      valueType: 'option',
      width: 220,
      fixed: 'right',
      render: (_: any, record: any) => (
        <Space size="small">
          <Button type="link" size="small" icon={<EditOutlined />} onClick={() => openModal(record)}>
            编辑
          </Button>
          {record.status !== 1 && (
            <Button type="link" size="small" icon={<VerticalAlignTopOutlined />} onClick={() => handleStatusChange(record, 1)}>
              发布
            </Button>
          )}
          {record.status === 1 && (
            <Button type="link" size="small" danger icon={<VerticalAlignBottomOutlined />} onClick={() => handleStatusChange(record, 2)}>
              下架
            </Button>
          )}
          <Popconfirm
            title="确认删除"
            description="删除后无法恢复，是否继续？"
            onConfirm={() => handleDelete(record.id)}
          >
            <Button type="link" danger size="small" icon={<DeleteOutlined />}>
              删除
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ];

  return (
    <PageContainer title="狗狗回顾">
      <ProTable
        columns={columns}
        actionRef={tableRef}
        request={async (params) => {
          const res = await request('/api/v1/admin/articles', {
            params: {
              page: params.current,
              page_size: params.pageSize,
              category: 'review',
              status: params.status,
              keyword: params.title,
            },
          });
          return { data: res.data?.articles || [], success: res.code === 200, total: res.data?.total || 0 };
        }}
        rowKey="id"
        search={{ labelWidth: 'auto' }}
        pagination={{ pageSize: 10, showSizeChanger: true }}
        scroll={{ x: 1300 }}
        toolBarRender={() => [
          <Button key="add" type="primary" icon={<PlusOutlined />} onClick={() => openModal()}>
            新建回顾
          </Button>,
        ]}
      />
      <ModalForm
        title={editData ? '编辑回顾' : '新建回顾'}
        open={modalVisible}
        onOpenChange={setModalVisible}
        onFinish={handleSubmit}
        form={form}
        width={900}
        modalProps={{
          destroyOnClose: true,
          afterClose: () => {
            setContent('');
            setCoverImageUrl('');
            setGallery([]);
            setEditData(null);
            form.resetFields();
          },
        }}
      >
        <ProFormText name="title" label="标题" rules={[{ required: true }]} />
        <Form.Item label="封面图" required>
          <Form.Item name="cover_image" noStyle rules={[{ required: true, message: '请上传封面图' }]}>
            <Input type="hidden" />
          </Form.Item>
          <Upload
            listType="picture-card"
            showUploadList={false}
            beforeUpload={handleCoverUpload}
            accept="image/*"
          >
            {coverImageUrl ? (
              <Image src={coverImageUrl} alt="cover" style={{ width: '100%', height: '100%', objectFit: 'cover' }} preview={false} />
            ) : (
              <div>
                {coverUploading ? <LoadingOutlined /> : <PlusOutlined />}
                <div style={{ marginTop: 8 }}>上传封面</div>
              </div>
            )}
          </Upload>
          {coverImageUrl && (
            <Button type="link" size="small" danger onClick={() => { setCoverImageUrl(''); form.setFieldsValue({ cover_image: '' }); }}>
              删除封面
            </Button>
          )}
        </Form.Item>
        <ProFormText name="location" label="活动地点" />
        <ProFormText name="event_date" label="活动日期" placeholder="如：2024.06.15" />
        <ProFormDigit name="participants" label="参与狗狗数量" min={0} initialValue={0} />
        <ProFormText name="summary" label="摘要" />
        <Form.Item label="图集">
          <div style={{ marginBottom: 16 }}>
            <Upload {...galleryUploadProps} showUploadList={false}>
              <Button icon={<UploadOutlined />}>上传图片</Button>
            </Upload>
            <span style={{ marginLeft: 8, color: '#999' }}>或直接输入图片URL：</span>
            <Input
              style={{ width: 300, marginLeft: 8 }}
              placeholder="输入图片URL"
              onPressEnter={(e: any) => {
                if (e.target.value) {
                  handleGalleryUpload(e.target.value);
                  e.target.value = '';
                }
              }}
            />
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
            {gallery.map((url, index) => (
              <div key={index} style={{ position: 'relative', width: 200, height: 150 }}>
                <img
                  src={url}
                  alt={`图集${index + 1}`}
                  style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 8 }}
                />
                <Button
                  type="primary"
                  danger
                  size="small"
                  icon={<DeleteOutlined />}
                  style={{ position: 'absolute', top: 8, right: 8 }}
                  onClick={() => removeGalleryImage(index)}
                >
                  删除
                </Button>
              </div>
            ))}
          </div>
        </Form.Item>
        <Form.Item label="内容" required>
          <ReactQuill
            ref={quillRef}
            theme="snow"
            value={content}
            onChange={setContent}
            modules={quillModules}
            formats={quillFormats}
            style={{ height: 300, marginBottom: 40 }}
          />
        </Form.Item>
        <ProFormText name="author_name" label="作者" />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '草稿', value: 0 },
            { label: '已发布', value: 1 },
            { label: '已下架', value: 2 },
          ]}
        />
        <ProFormDigit name="is_top" label="置顶" min={0} max={1} />
        <ProFormDigit name="sort_order" label="排序" min={0} />
      </ModalForm>
    </PageContainer>
  );
}

